<title>The Folded Library</title><style>
:root{--paper:#f7f0df;--ink:#202d40;--blue:#1749b0;--red:#ca3624;--gold:#efc542}
*{box-sizing:border-box}body{margin:0;background:var(--paper);color:var(--ink);font-family:"Palatino Linotype",Palatino,serif;line-height:1.5}main{max-width:1120px;margin:auto;padding:28px}a{color:var(--blue)}nav{display:flex;justify-content:space-between;gap:20px;border-bottom:2px solid var(--ink);padding-bottom:16px;font-family:"Courier New",monospace;font-size:13px}.eyebrow{font-family:"Courier New",monospace;text-transform:uppercase;letter-spacing:2px;font-size:12px;font-weight:bold}header{display:grid;grid-template-columns:1.2fr 1fr;gap:30px;padding:42px 0;align-items:center}h1{font-size:clamp(52px,8vw,96px);line-height:.9;letter-spacing:-4px;margin:16px 0 24px;font-weight:normal}h1 em{color:var(--red)}header p{font-size:20px;max-width:500px}.hero{position:relative;transform:rotate(2deg);border:2px solid var(--ink);background:#fff8e9;box-shadow:8px 8px 0 var(--blue);margin:0}.hero img{display:block;width:100%;aspect-ratio:3/2;object-fit:cover}.hero figcaption{padding:12px;font-family:"Courier New",monospace;font-size:12px;border-top:1px solid var(--ink)}.tabs{display:flex;gap:8px;margin-bottom:24px}button,input,select{font:inherit}button{cursor:pointer;border:2px solid var(--ink);background:var(--paper);color:var(--ink);padding:11px 17px;min-height:46px;box-shadow:3px 3px 0 var(--ink);transition:transform .15s}button:hover{transform:translateY(-2px)}button:active{transform:translate(2px,2px);box-shadow:none}button[aria-selected=true],.primary{background:var(--blue);color:white}button:disabled{opacity:.5;cursor:default}button:focus-visible,input:focus-visible,select:focus-visible,a:focus-visible{outline:3px solid var(--red);outline-offset:4px}section{border:2px solid var(--ink);padding:28px;background:#fffbf2}h2{font-size:32px;line-height:1.1;margin:8px 0 16px;font-weight:normal}.bench{display:grid;grid-template-columns:1fr 1.2fr;gap:32px}.spread{display:grid;grid-template-columns:1fr 1fr;min-height:220px;margin:24px 0;box-shadow:5px 6px 0 #dfd6c3;position:relative}.leaf{background:#fff;border:1px solid #bfb7a6;display:flex;align-items:center;justify-content:center;flex-direction:column;color:var(--blue);font-size:64px;line-height:1}.leaf+ .leaf{border-left:2px dashed #baa98b;color:var(--red)}.leaf small{font-size:12px;margin-top:18px;font-family:"Courier New",monospace;letter-spacing:1px}.bank{display:flex;gap:10px;flex-wrap:wrap}.bank button{font-family:"Courier New",monospace;font-size:23px;min-width:54px}.status{min-height:76px;background:#f3e6c7;border-left:5px solid var(--gold);padding:14px;margin:20px 0}.actions{display:flex;gap:12px;flex-wrap:wrap}.note{font-size:15px;color:#4e5868}label{display:block;margin:16px 0 6px}input,select{padding:10px;border:2px solid var(--ink);background:white;width:100%;max-width:340px}table{border-collapse:collapse;width:100%;margin:24px 0;font-family:"Courier New",monospace;font-size:14px}td,th{text-align:left;padding:12px 8px;border-bottom:1px solid #c7bcaa}th{background:var(--ink);color:white}.receipt{border:2px dashed var(--blue);padding:20px}.receipt strong{font-size:42px;color:var(--red);display:block}footer{padding:30px 0;font-size:14px}.steps{display:flex;gap:12px;list-style:none;padding:0}.steps li{flex:1;border-top:4px solid var(--red);padding-top:12px}.steps b{display:block;color:var(--blue)}[hidden]{display:none!important}@media(max-width:700px){main{padding:20px}header,.bench{grid-template-columns:1fr}header{padding-top:30px}h1{letter-spacing:-2px}.hero{max-width:480px;margin:0 8px 15px 0}section{padding:20px}nav{font-size:11px}.spread{min-height:180px}.tabs button{flex:1;padding:10px}.steps{font-size:14px}.bench{gap:12px}}@media(prefers-reduced-motion:reduce){*{transition:none!important}}@media print{nav,header,.tabs,#puzzle,.actions,footer,.note{display:none!important}main{padding:0}section{border:0}.bench{display:block}body{background:white}h2{font-size:24px}.receipt strong{font-size:28px}table{font-size:11px}}
</style></head><body><main>
<nav><a href="index.php">← Chloe Reads Jon</a><span>PRINT SHOP / No. 006 • OCT 2026</span></nav>
<header><div><div class="eyebrow">Small paper. Big plot twist.</div><h1>The Folded<br><em>Library.</em></h1><p>A book’s pages don’t start in reading order. Become the tiny print-shop apprentice who makes the chaos fold into sense.</p></div>
<figure class="hero"><img src="?art=1" alt="Original print-shop illustration: a flat sheet becomes nested folded sheets, then a pocket booklet"><figcaption>01 / LAY OUT → 02 / NEST &amp; FOLD → 03 / READ</figcaption></figure></header>
<div class="tabs" role="tablist" aria-label="Workshop mode"><button id="gameTab" role="tab" aria-selected="true" aria-controls="puzzle">Play the page puzzle</button><button id="planTab" role="tab" aria-selected="false" aria-controls="planner">Plan a real booklet</button></div>
<section id="puzzle" role="tabpanel" aria-labelledby="gameTab"><div class="bench"><div><div class="eyebrow" id="round"></div><h2 id="challenge"></h2><p id="brief"></p><div class="bank" id="bank" aria-label="Choose page numbers"></div><div class="status" id="feedback" role="status" aria-live="polite">Tap two numbers: left page first, then right page.</div><div class="actions"><button id="check" class="primary">Fold &amp; inspect</button><button id="clear">Clear sheet</button><button id="hint">A small hint</button><button id="next" hidden>Next sheet →</button></div></div><div><div class="eyebrow">Your sheet • viewed before folding</div><div class="spread"><div class="leaf"><span id="left">?</span><small>LEFT PAGE</small></div><div class="leaf"><span id="right">?</span><small>RIGHT PAGE</small></div></div><p class="note">One sheet, two sides, four book pages. All pages are upright in this left-to-right booklet. The dashed line is the spine.</p><ol class="steps"><li><b>1. Pair</b>Far-apart pages become neighbours.</li><li><b>2. Nest</b>Outer sheets wrap around inner sheets.</li><li><b>3. Fold</b>The reading order finally appears.</li></ol></div></div></section>
<section id="planner" hidden role="tabpanel" aria-labelledby="planTab"><div class="bench"><div><div class="eyebrow">One nested booklet • left-to-right</div><h2>Make the paper behave.</h2><label for="pages">Content pages, including the cover</label><input id="pages" type="number" min="1" max="80" value="12"><p class="note">Up to 80 pages. Blank pages are added at the end to reach a multiple of four.</p><label for="title">Name your little book</label><input id="title" maxlength="80" value="My pocket field guide"><div class="status" id="planStatus" role="status"></div><div class="actions"><button id="print" class="primary">Print the plan</button><button id="download">Save page-order list</button></div><p class="note">This is a page-placement plan, not a PDF rearranger. For actual printing use your PDF reader’s booklet mode: landscape, two pages per side, duplex short-edge binding. Don’t impose the pages twice.</p></div><div class="receipt"><div class="eyebrow" id="bookTitle"></div><strong id="sheetCount"></strong><span id="countDetails"></span><table><caption>Sheet order: outermost to innermost</caption><thead><tr><th>Sheet</th><th>Front L | R</th><th>Back L | R</th></tr></thead><tbody id="orders"></tbody></table><p class="note">Print a single test sheet first. Printer feed direction and manual duplex stack order vary. Nest sheets in the order above and fold through the centre.</p></div></div></section>
<footer>Inspired by Jon’s <a href="?source=1">Caritas in Veritate in booklet form</a>, where he made a long encyclical into a little paper book. A small homage to the satisfying magic of folding.</footer>
</main><script>
'use strict';
const $=id=>document.getElementById(id);
const jobs=[
{n:8,pair:[8,1],name:'The cover has a secret neighbour.',brief:'An eight-page comic needs its outermost front side. Page 1 belongs on the right. What wraps around to meet it?',hint:'The back cover sits beside the front cover on an unfolded sheet.'},
{n:8,pair:[2,7],name:'Turn that cover sheet over.',brief:'Same eight-page comic. Now lay out the BACK of its outer sheet, viewed upright.',hint:'Page 2 goes behind page 1. Page 7 goes behind page 8.'},
{n:12,pair:[10,3],name:'One sheet deeper.',brief:'A twelve-page field guide needs the FRONT of its second sheet, counting from the outside.',hint:'Outer front is 12 | 1. Move two page numbers inward on each side.'},
{n:12,pair:[4,9],name:'The other side of the story.',brief:'Now arrange the BACK of that second sheet in the twelve-page guide.',hint:'The left page is 4. Its partner makes their total 13.'},
{n:16,pair:[8,9],name:'Meet in the middle.',brief:'A sixteen-page mini magazine needs the BACK of the innermost sheet. This is the centre spread.',hint:'At the centre, two consecutive pages finally get to sit together.'}
];let step=0,picks=[],done=false;
function render(){const j=jobs[step];$('round').textContent='APPRENTICE SHEET '+(step+1)+' / '+jobs.length;$('challenge').textContent=j.name;$('brief').textContent=j.brief;$('bank').replaceChildren();for(let i=1;i<=j.n;i++){const b=document.createElement('button');b.textContent=i;b.setAttribute('aria-label','Place page '+i);b.onclick=()=>{if(done)return;if(picks.length===2)picks=[];picks.push(i);draw();};$('bank').append(b);}picks=[];done=false;draw();$('feedback').textContent='Tap two numbers: left page first, then right page.';$('next').hidden=true;$('check').disabled=false;}
function draw(){$('left').textContent=picks[0]??'?';$('right').textContent=picks[1]??'?';[...$('bank').children].forEach(b=>{b.disabled=done||picks.includes(Number(b.textContent));});}
$('clear').onclick=()=>{if(done)return;picks=[];draw();$('feedback').textContent='Fresh sheet. Pick the left and right pages.';};
$('hint').onclick=()=>{$('feedback').textContent=jobs[step].hint;};
$('check').onclick=()=>{if(picks.length!==2){$('feedback').textContent='The press needs both halves filled. Choose two numbers first.';return;}const j=jobs[step];if(picks.every((p,i)=>p===j.pair[i])){done=true;draw();$('check').disabled=true;$('feedback').textContent=step===4?'Perfect fold. All five sheets solved! You now know the print-shop secret: paired page numbers add up to the total page count plus one.':'Perfect fold! '+picks.join(' + ')+' = '+(j.n+1)+'. Paired pages always total one more than the booklet’s page count.';$('next').hidden=false;$('next').textContent=step===4?'Play again ↻':'Next sheet →';}else{$('feedback').textContent=picks[0]+picks[1]===j.n+1?'The pair adds up correctly, but this is the wrong side or sheet. Check which sheet the brief asks for.':'Not quite: these paired pages should add up to '+(j.n+1)+'. Try a new pair, or ask for a hint.';}};
$('next').onclick=()=>{step=(step+1)%jobs.length;render();};
function mode(plan){$('planner').hidden=!plan;$('puzzle').hidden=plan;$('planTab').setAttribute('aria-selected',String(plan));$('gameTab').setAttribute('aria-selected',String(!plan));}
$('gameTab').onclick=()=>mode(false);$('planTab').onclick=()=>mode(true);
[ $('gameTab'),$('planTab') ].forEach(b=>b.onkeydown=e=>{if(e.key==='ArrowLeft'||e.key==='ArrowRight'){e.preventDefault();const plan=b.id==='gameTab';mode(plan);$(plan?'planTab':'gameTab').focus();}});
let rows=[],contentPages=12,total=12;
function plan(){contentPages=Number($('pages').value);const valid=Number.isInteger(contentPages)&&contentPages>=1&&contentPages<=80;$('print').disabled=$('download').disabled=!valid;if(!valid){$('planStatus').textContent='Enter a whole number from 1 to 80.';return;}total=Math.ceil(contentPages/4)*4;rows=[];$('orders').replaceChildren();const label=p=>p>contentPages?'Blank ('+p+')':String(p);for(let i=0;i<total/4;i++){const r=[total-2*i,1+2*i,2+2*i,total-1-2*i];rows.push(r);const tr=document.createElement('tr');[i+1,label(r[0])+' | '+label(r[1]),label(r[2])+' | '+label(r[3])].forEach(t=>{const td=document.createElement('td');td.textContent=t;tr.append(td);});$('orders').append(tr);}$('bookTitle').textContent=$('title').value||'Untitled little book';$('sheetCount').textContent=total/4+' sheets';$('countDetails').textContent=contentPages+' content pages + '+(total-contentPages)+' blanks = '+total+' booklet pages.';$('planStatus').textContent='Paper arithmetic: one folded, double-sided sheet holds four pages. '+(total>40?'For a thick booklet, consider smaller sections and check your printer’s paper limits.':'Your outermost sheet pairs the last page with page 1.');}
$('pages').oninput=plan;$('title').oninput=plan;$('print').onclick=()=>window.print();
$('download').onclick=()=>{const lines=[($('title').value||'Untitled little book'),contentPages+' content pages; '+total+' total pages; '+total/4+' sheets.','Sheet,Front left,Front right,Back left,Back right',...rows.map((r,i)=>[i+1,...r.map(p=>p>contentPages?'Blank ('+p+')':p)].join(',')),'Place pages upright. Landscape duplex: short-edge binding. Test one sheet first.'];const u=URL.createObjectURL(new Blob([lines.join('\n')],{type:'text/plain'}));const a=document.createElement('a');a.href=u;a.download='booklet-page-order.txt';a.click();setTimeout(()=>URL.revokeObjectURL(u),1000);};
render();plan();
</script></body></html>
